// Asset-only additions. The generic guide keeps ownership of privacy and feature gates.
for(const group of document.querySelectorAll('[data-av-foundation-tabs]'))group.addEventListener('click',event=>{const button=event.target.closest('[role=tab]');if(!button||button.disabled)return;for(const tab of group.querySelectorAll('[role=tab]'))tab.setAttribute('aria-selected',String(tab===button));});
for(const overview of document.querySelectorAll('[data-asset-overview]'))overview.addEventListener('click',event=>{
 const currency=event.target.closest('[data-asset-currency]');if(currency){for(const tab of overview.querySelectorAll('[data-asset-currency]'))tab.setAttribute('aria-selected',String(tab===currency));for(const panel of overview.querySelectorAll('[data-asset-currency-panel]'))panel.hidden=panel.dataset.assetCurrencyPanel!==currency.dataset.assetCurrency;overview.querySelector('[data-asset-unit]').textContent=currency.dataset.assetCurrency==='converted'?'CNY':currency.dataset.assetCurrency;return;}
 const chart=event.target.closest('[data-asset-chart]');if(chart){for(const tab of overview.querySelectorAll('[data-asset-chart]'))tab.setAttribute('aria-selected',String(tab===chart));overview.querySelector('[data-asset-chart-title]').textContent='资产概览';return;}
 const filter=event.target.closest('[data-asset-filter]');if(filter){for(const tab of overview.querySelectorAll('[data-asset-filter]'))tab.setAttribute('aria-selected',String(tab===filter));for(const section of overview.querySelectorAll('[data-asset-kind]'))section.hidden=filter.dataset.assetFilter!=='all'&&section.dataset.assetKind!==filter.dataset.assetFilter;return;}
 const group=event.target.closest('[data-asset-group]');if(group){const expanded=group.getAttribute('aria-expanded')!=='true';group.setAttribute('aria-expanded',String(expanded));group.nextElementSibling.hidden=!expanded;return;}
 const row=event.target.closest('[data-asset-row]');if(row)overview.querySelector('[data-asset-result]').textContent='已选择账户详情：'+row.dataset.assetRow+'。完整原流程见资产页交互设计。';
});
